import type {
  CookiesAttributes,
  ProcessedCookieAttributes,
  ProcessedStorageAttributes,
  RoutingStorageInput,
  StorageAttributes,
} from '@intlayer/types/config';
import {
  COOKIE_NAME,
  HEADER_NAME,
  LOCALE_STORAGE_NAME,
} from '../defaultValues/routing';

// ============================================================================
// Types
// ============================================================================

type CookieEntry = {
  name: string;
  attributes: ProcessedCookieAttributes;
};

/** Number of seconds in a day, used to convert a `number` of days. */
const SECONDS_PER_DAY = 60 * 60 * 24;

type WebStorageEntry = {
  name: string;
};

type HeaderEntry = {
  name: string;
};

type StorageEntry =
  | 'cookie'
  | 'localStorage'
  | 'sessionStorage'
  | 'header'
  | CookiesAttributes
  | StorageAttributes;

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Merges the user-facing `expires` and `maxAge` into a single, normalized and
 * serialization-safe expiry consumed by the client runtime.
 *
 * Precedence and normalization:
 * - `maxAge` (seconds) wins when set and is the internal unit (relative);
 * - `expires` as a `number` is interpreted as **days** and converted to
 *   seconds (relative);
 * - `expires` as a `Date` (possibly a cross-realm instance, since config files
 *   run in a `node:vm` sandbox) or an ISO string becomes an ISO **string**
 *   (absolute). Strings survive `JSON.stringify`, unlike a `Date`.
 *
 * The result is therefore: a `number` = seconds from creation, a `string` =
 * absolute ISO date, or `undefined` for a session cookie.
 */
const normalizeCookieExpiry = (
  expires: CookiesAttributes['expires'],
  maxAge: CookiesAttributes['maxAge']
): number | string | undefined => {
  if (typeof maxAge === 'number') return maxAge;
  if (expires === undefined) return undefined;
  if (
    expires instanceof Date ||
    Object.prototype.toString.call(expires) === '[object Date]'
  ) {
    return (expires as Date).toISOString();
  }
  if (typeof expires === 'string') return expires;
  return expires * SECONDS_PER_DAY;
};

const createCookieEntry = (
  options?: Partial<CookiesAttributes>
): CookieEntry => {
  const {
    name,
    path = '/',
    expires,
    maxAge,
    domain,
    secure,
    sameSite,
    httpOnly,
  } = options ?? {};
  return {
    name: name ?? COOKIE_NAME,
    attributes: {
      path,
      expires: normalizeCookieExpiry(expires, maxAge),
      domain,
      secure,
      sameSite,
      httpOnly,
    },
  };
};

const createWebStorageEntry = (
  options?: Partial<StorageAttributes>
): WebStorageEntry => ({
  name: options?.name ?? LOCALE_STORAGE_NAME,
});

const createHeaderEntry = (
  options?: Partial<StorageAttributes>
): HeaderEntry => ({
  name: options?.name ?? HEADER_NAME,
});

const isCookieEntry = (entry: unknown): boolean => {
  if (typeof entry !== 'object' || entry === null) return false;
  const e = entry as Record<string, unknown>;
  return (
    e['type'] === 'cookie' ||
    'sameSite' in e ||
    'httpOnly' in e ||
    'secure' in e
  );
};

const isStorageType = (
  value: string
): value is 'cookie' | 'localStorage' | 'sessionStorage' | 'header' =>
  value === 'cookie' ||
  value === 'localStorage' ||
  value === 'sessionStorage' ||
  value === 'header';

// ============================================================================
// Main Function
// ============================================================================

const processStorageEntry = (
  entry: StorageEntry
): Partial<ProcessedStorageAttributes> => {
  if (typeof entry === 'string') {
    if (!isStorageType(entry)) {
      return { cookies: [], localStorage: [], sessionStorage: [], headers: [] };
    }
    if (entry === 'cookie') return { cookies: [createCookieEntry()] };
    if (entry === 'localStorage')
      return { localStorage: [createWebStorageEntry()] };
    if (entry === 'sessionStorage')
      return { sessionStorage: [createWebStorageEntry()] };
    if (entry === 'header') return { headers: [createHeaderEntry()] };
  }

  if (typeof entry === 'object' && entry !== null) {
    const typedEntry = entry as CookiesAttributes | StorageAttributes;

    if (isCookieEntry(typedEntry)) {
      return { cookies: [createCookieEntry(typedEntry as CookiesAttributes)] };
    }
    if ('type' in typedEntry && typedEntry.type === 'localStorage') {
      return {
        localStorage: [createWebStorageEntry(typedEntry as StorageAttributes)],
      };
    }
    if ('type' in typedEntry && typedEntry.type === 'sessionStorage') {
      return {
        sessionStorage: [
          createWebStorageEntry(typedEntry as StorageAttributes),
        ],
      };
    }
    if ('type' in typedEntry && typedEntry.type === 'header') {
      return { headers: [createHeaderEntry(typedEntry as StorageAttributes)] };
    }
    // Default to localStorage for ambiguous objects
    return {
      localStorage: [
        createWebStorageEntry(typedEntry as Omit<StorageAttributes, 'type'>),
      ],
    };
  }

  return { cookies: [], localStorage: [], sessionStorage: [], headers: [] };
};

const mergeStorageAttributes = (
  accumulated: ProcessedStorageAttributes,
  partial: Partial<ProcessedStorageAttributes>
): ProcessedStorageAttributes => ({
  cookies: [...(accumulated.cookies ?? []), ...(partial.cookies ?? [])],
  localStorage: [
    ...(accumulated.localStorage ?? []),
    ...(partial.localStorage ?? []),
  ],
  sessionStorage: [
    ...(accumulated.sessionStorage ?? []),
    ...(partial.sessionStorage ?? []),
  ],
  headers: [...(accumulated.headers ?? []), ...(partial.headers ?? [])],
});

/**
 * Extracts and normalizes storage configuration into separate arrays for each storage type.
 * Called at config-build time so the result is pre-computed and stored in the config.
 *
 * @param options - The storage configuration from IntlayerConfig
 * @returns An object containing arrays for cookies, localStorage, sessionStorage and headers
 */
export const getStorageAttributes = (
  options: RoutingStorageInput
): ProcessedStorageAttributes => {
  const emptyResult: ProcessedStorageAttributes = {
    cookies: [],
    localStorage: [],
    sessionStorage: [],
    headers: [],
  };

  if (options === false || options === undefined) return {};

  const result = Array.isArray(options)
    ? options.reduce<ProcessedStorageAttributes>((acc, entry) => {
        const partial = processStorageEntry(entry);
        return mergeStorageAttributes(acc, partial);
      }, emptyResult)
    : mergeStorageAttributes(emptyResult, processStorageEntry(options));

  // Remove empty arrays
  const cleanedResult: ProcessedStorageAttributes = {};

  if (result.cookies && result.cookies.length > 0) {
    cleanedResult.cookies = result.cookies;
  }

  if (result.localStorage && result.localStorage.length > 0) {
    cleanedResult.localStorage = result.localStorage;
  }

  if (result.sessionStorage && result.sessionStorage.length > 0) {
    cleanedResult.sessionStorage = result.sessionStorage;
  }

  if (result.headers && result.headers.length > 0) {
    cleanedResult.headers = result.headers;
  }

  return cleanedResult;
};
